namespace Tulaziva.Domain.Entities;

public class AdImage
{
    public Guid Id { get; set; } = Guid.NewGuid();

    public Guid AdId { get; set; }
    public Ad Ad { get; set; } = null!;

    /// <summary>Path of the file inside the storage, with "/" as separator. Generated by the server, never taken from the client.</summary>
    public string StoragePath { get; set; } = string.Empty;

    public string ContentType { get; set; } = string.Empty;

    public long SizeBytes { get; set; }

    /// <summary>Order in the gallery. The first one is the cover.</summary>
    public int Position { get; set; }

    public DateTime CreatedAtUtc { get; set; } = DateTime.UtcNow;
}
